    "question": "Hyperconjugation involves the delocalization of:",
    "options": {
      "A": "Electrons of a C-H sigma bond into an adjacent empty p orbital or pi bond",
      "B": "Electrons of a pi bond into an adjacent sigma orbital",
      "C": "Lone pair electrons into a sigma antibonding orbital",
      "D": "Sigma electrons into a non-bonding d orbital"
    },
    "optionsList": [
      "Electrons of a C-H sigma bond into an adjacent empty p orbital or pi bond",
      "Electrons of a pi bond into an adjacent sigma orbital",
      "Lone pair electrons into a sigma antibonding orbital",
      "Sigma electrons into a non-bonding d orbital"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nMechanism of hyperconjugation (Baker-Nathan effect).\n\n2. GIVEN:\nInteraction between sigma(C-H) and adjacent vacant p orbital.\n\n3. FORMULA / PRINCIPLE:\nNo-bond resonance delocalizing sigma electrons into adjacent conjugated pi or empty p system.\n\n4. STEP-BY-STEP SOLUTION:\n1. Hyperconjugation is the interaction of sigma electrons of a C-H or C-C bond with an adjacent empty p-orbital (carbocation), half-filled p-orbital (radical), or pi system (alkene).\n2. It is also described as sigma-p or sigma-pi* orbital overlap.\n3. Because no covalent bond exists between carbon and hydrogen in the contributing structures, it is termed 'no-bond resonance'.\n\n5. FINAL ANSWER:\nOption A: Electrons of a C-H sigma bond into an adjacent empty p orbital or pi bond\n\n6. WHY OTHER OPTIONS ARE WRONG:\nHyperconjugation requires sigma(C-H) overlap with adjacent vacant p or pi orbitals, not d orbitals.",
    "solutionStructured": {
      "concept": "Mechanism of hyperconjugation (Baker-Nathan effect).",
      "given": "Interaction between sigma(C-H) and adjacent vacant p orbital.",
      "formula": "No-bond resonance delocalizing sigma electrons into adjacent conjugated pi or empty p system.",
      "stepByStep": "1. Hyperconjugation is the interaction of sigma electrons of a C-H or C-C bond with an adjacent empty p-orbital (carbocation), half-filled p-orbital (radical), or pi system (alkene).\n2. It is also described as sigma-p or sigma-pi* orbital overlap.\n3. Because no covalent bond exists between carbon and hydrogen in the contributing structures, it is termed 'no-bond resonance'.",
      "finalAnswer": "Option A: Electrons of a C-H sigma bond into an adjacent empty p orbital or pi bond",
      "whyOtherOptionsWrong": "Hyperconjugation requires sigma(C-H) overlap with adjacent vacant p or pi orbitals, not d orbitals."
    },
