    "id": "organic-mcq-323",
    "questionNumber": 323,
    "question": "In Dumas method for estimation of nitrogen, 0.30 g of an organic compound gave 50 mL of nitrogen collected at 300 K and 715 mm pressure. (Aqueous tension at 300 K = 15 mm). The percentage of nitrogen in the compound is:",
    "options": {
      "A": "17.46%",
      "B": "22.50%",
      "C": "14.20%",
      "D": "28.80%"
    },
    "optionsList": [
      "17.46%",
      "22.50%",
      "14.20%",
      "28.80%"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nDumas method quantitative calculation.\n\n2. GIVEN:\nMass = 0.30 g, V = 50 mL, T = 300 K, P_dry = 715 - 15 = 700 mm Hg.\n\n3. FORMULA / PRINCIPLE:\nV_STP = (P * V * 273) / (760 * T); %N = (28 * V_STP * 100) / (22400 * mass).\n\n4. STEP-BY-STEP SOLUTION:\n1. Step 1: Calculate dry gas pressure P1 = P_observed - aqueous tension = 715 - 15 = 700 mm Hg.\n2. Step 2: Convert nitrogen volume to STP: V_STP = (700 * 50 * 273) / (760 * 300) = 9555000 / 228000 = 41.91 mL.\n3. Step 3: Mass of N2 at STP = (28 g / 22400 mL) * 41.91 mL = 0.05238 g.\n4. Step 4: % Nitrogen = (0.05238 g / 0.30 g) * 100 = 17.46%.\n\n5. FINAL ANSWER:\nOption A: 17.46%\n\n6. WHY OTHER OPTIONS ARE WRONG:\nMust subtract aqueous tension to obtain the true partial pressure of dry N2 gas before STP conversion.",
    "solutionStructured": {
      "concept": "Dumas method quantitative calculation.",
      "given": "Mass = 0.30 g, V = 50 mL, T = 300 K, P_dry = 715 - 15 = 700 mm Hg.",
      "formula": "V_STP = (P * V * 273) / (760 * T); %N = (28 * V_STP * 100) / (22400 * mass).",
      "stepByStep": "1. Step 1: Calculate dry gas pressure P1 = P_observed - aqueous tension = 715 - 15 = 700 mm Hg.\n2. Step 2: Convert nitrogen volume to STP: V_STP = (700 * 50 * 273) / (760 * 300) = 9555000 / 228000 = 41.91 mL.\n3. Step 3: Mass of N2 at STP = (28 g / 22400 mL) * 41.91 mL = 0.05238 g.\n4. Step 4: % Nitrogen = (0.05238 g / 0.30 g) * 100 = 17.46%.",
      "finalAnswer": "Option A: 17.46%",
      "whyOtherOptionsWrong": "Must subtract aqueous tension to obtain the true partial pressure of dry N2 gas before STP conversion."
    },
