      "given": "p-NO2, -H, p-CH3, p-OCH3 substituted benzoic acids.",
      "formula": "Electron-withdrawing groups (-M, -I) stabilize the carboxylate conjugate base; electron-donating groups (+M, +I) destabilize it.",
      "stepByStep": "1. p-Nitro group (-NO2) exerts strong -M and -I electron-withdrawing effects, dispersing the negative charge on -COO- and markedly increasing acidity.\n2. Benzoic acid has no substituent.\n3. p-Methyl group (-CH3) is weakly electron-donating through hyperconjugation (+I), slightly decreasing acidity.\n4. p-Methoxy group (-OCH3) donates electron density strongly into the ring via resonance (+M > -I), greatly destabilizing the carboxylate ion and making it the weakest acid.\n5. Order: p-Nitrobenzoic acid > Benzoic acid > p-Methylbenzoic acid > p-Methoxybenzoic acid.",
