    "explanation": "1. CONCEPT:\nStereochemical criteria for geometrical isomerism.\n\n2. GIVEN:\nSubstituted ethenes.\n\n3. FORMULA / PRINCIPLE:\nRestricted rotation about C=C with non-identical groups on each double-bonded carbon.\n\n4. STEP-BY-STEP SOLUTION:\n1. In 1,2-dichloroethene, each sp2 carbon atom is bonded to two different atoms (-H and -Cl).\n2. This allows cis-1,2-dichloroethene (both Cl on same side, dipole moment > 0) and trans-1,2-dichloroethene (opposite sides, dipole moment = 0).\n3. In 1,1-dichloroethene, one carbon holds two identical Cl atoms, so swapping groups produces the exact same structure.\n\n5. FINAL ANSWER:\nOption A: 1,2-Dichloroethene (ClCH=CHCl)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nCis-trans isomerism requires that neither double-bonded carbon atom carries two identical substituents.",
